/**
 * Microsoft SharePoint Trigger Node - Version 1
 * Starts a workflow when a file or list item changes in Microsoft SharePoint
 */


export interface MicrosoftSharePointTriggerV1Params {
/**
 * Time at which polling should occur
 * @default {"item":[{"mode":"everyMinute"}]}
 */
    pollTimes?: {
        /** Item
     */
    item?: Array<{
      /** How often to trigger.
       * @default everyDay
       */
      mode?: 'everyMinute' | 'everyHour' | 'everyDay' | 'everyWeek' | 'everyMonth' | 'everyX' | 'custom' | Expression<string>;
      /** The hour of the day to trigger (24h format)
       * @displayOptions.hide { mode: ["custom", "everyHour", "everyMinute", "everyX"] }
       * @default 14
       */
      hour?: number | Expression<number>;
      /** The minute past the hour to trigger (0-59)
       * @displayOptions.hide { mode: ["custom", "everyMinute", "everyX"] }
       * @default 0
       */
      minute?: number | Expression<number>;
      /** The day of the month to trigger
       * @displayOptions.show { mode: ["everyMonth"] }
       * @default 1
       */
      dayOfMonth?: number | Expression<number>;
      /** The weekday to trigger
       * @displayOptions.show { mode: ["everyWeek"] }
       * @default 1
       */
      weekday?: '1' | '2' | '3' | '4' | '5' | '6' | '0' | Expression<string>;
      /** Use custom cron expression. Values and ranges as follows:&lt;ul&gt;&lt;li&gt;Seconds: 0-59&lt;/li&gt;&lt;li&gt;Minutes: 0 - 59&lt;/li&gt;&lt;li&gt;Hours: 0 - 23&lt;/li&gt;&lt;li&gt;Day of Month: 1 - 31&lt;/li&gt;&lt;li&gt;Months: 0 - 11 (Jan - Dec)&lt;/li&gt;&lt;li&gt;Day of Week: 0 - 6 (Sun - Sat)&lt;/li&gt;&lt;/ul&gt;
       * @displayOptions.show { mode: ["custom"] }
       * @default * * * * * *
       */
      cronExpression?: string | Expression<string>;
      /** All how many X minutes/hours it should trigger
       * @displayOptions.show { mode: ["everyX"] }
       * @default 2
       */
      value?: number | Expression<number>;
      /** If it should trigger all X minutes or hours
       * @displayOptions.show { mode: ["everyX"] }
       * @default hours
       */
      unit?: 'minutes' | 'hours' | Expression<string>;
    }>;
  };
  authentication?: 'microsoftOAuth2Api' | 'microsoftEntraServicePrincipalApi';
/**
 * The SharePoint site holding the library to watch
 * @searchListMethod getSites
 * @default {"mode":"list","value":""}
 */
    site?: { __rl: true; mode: 'list' | 'url' | 'id'; value: string; cachedResultName?: string };
/**
 * Resource
 * @displayOptions.hide { site: [""] }
 * @default documentLibrary
 */
    resource?: 'documentLibrary' | 'list';
/**
 * The document library to watch for changes
 * @searchListMethod getDrives
 * @displayOptions.show { resource: ["documentLibrary"] }
 * @displayOptions.hide { site: [""] }
 * @default {"mode":"list","value":""}
 */
    drive?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * The list to watch for changes
 * @searchListMethod getLists
 * @displayOptions.show { resource: ["list"] }
 * @displayOptions.hide { site: [""] }
 * @default {"mode":"list","value":""}
 */
    list?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Which changes in the library start the workflow
 * @default ["changed","deleted"]
 */
    events?: Array<'changed' | 'deleted'>;
}

export interface MicrosoftSharePointTriggerV1Credentials {
  microsoftOAuth2Api: CredentialReference;
  microsoftEntraServicePrincipalApi: CredentialReference;
}

interface MicrosoftSharePointTriggerV1NodeBase {
  type: 'n8n-nodes-base.microsoftSharePointTrigger';
  version: 1;
  isTrigger: true;
}

export type MicrosoftSharePointTriggerV1ParamsNode = MicrosoftSharePointTriggerV1NodeBase & {
  config: NodeConfig<MicrosoftSharePointTriggerV1Params> & { credentials?: MicrosoftSharePointTriggerV1Credentials };
};

export type MicrosoftSharePointTriggerV1Node = MicrosoftSharePointTriggerV1ParamsNode;